document.addEventListener("DOMContentLoaded",()=>{const e=document.querySelectorAll(".domains-section__card");if(!e.length)return;if(window.matchMedia("(prefers-reduced-motion: reduce)").matches||"undefined"==typeof IntersectionObserver)return void e.forEach(e=>e.classList.add("is-visible"));const t=new IntersectionObserver(e=>{e.forEach(e=>{e.isIntersecting&&(e.target.classList.add("is-visible"),t.unobserve(e.target))})},{threshold:.2});e.forEach((e,s)=>{e.style.transitionDelay=100*s+"ms",t.observe(e)})});